        if (q !== 4'd1) begin
            $display("Error: Expected q = 1 after reset, got q = %d", q);
            errors = errors + 1;
        end

        // Count up to 10
        repeat (9) begin
            #10; // Wait for clock edge
            if (q !== (q - 1) + 1) begin
                $display("Error: Counting error at q = %d", q);
                errors = errors + 1;
            end
        end

        // Check that it wraps around correctly
        #10; // Wait for clock edge
        if (q !== 4'd1) begin
            $display("Error: Expected q = 1 after reaching 10, got q = %d", q);
            errors = errors + 1;
        end

        // Test illegal transition (reset during counting)
        reset = 1; #10;
        if (q !== 4'd1) begin
            $display("Error: Reset during counting did not set q to 1. q = %d", q);
            errors = errors + 1;
        end

        // Final check for any errors
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end
endmodule
